    phuongAn: ["F<sub>tính</sub> = 3,27 < F<sub>bảng</sub> = 6,94 → độ chụm không khác nhau có ý nghĩa", "F<sub>tính</sub> = 0,09 < F<sub>bảng</sub> = 6,94 → độ chụm không khác nhau có ý nghĩa", "F<sub>tính</sub> = 10,71 < F<sub>bảng</sub>(4, 2) = 19,25 → độ chụm không khác nhau có ý nghĩa", "F<sub>tính</sub> = 10,71 > F<sub>bảng</sub> = 6,94 → có độ chụm khác nhau có ý nghĩa"],
